17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Map;
23	import java.util.Objects;
24	
25	import jakarta.servlet.http.HttpServletRequest;
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.dao.DataIntegrityViolationException;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ProblemDetail;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
33	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
34	import org.springframework.security.access.AccessDeniedException;
35	import org.springframework.validation.BindingResult;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles exception thrown by Bean Validation on controller methods parameters
128	     *
129	     * @param e The {@link MethodArgumentNotValidException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
132	     */
133	    @ExceptionHandler(MethodArgumentNotValidException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
136	        HttpStatus status = HttpStatus.BAD_REQUEST;
137	        BindingErrorsResponse errors = new BindingErrorsResponse();
138	        BindingResult bindingResult = e.getBindingResult();
139	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
140	        if (bindingResult.hasErrors()) {
141	            errors.addAllErrors(bindingResult);
142	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
143	                .map(fieldError -> {
144	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
145	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
146	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
147	                        fieldError.getField(),
148	                        defaultMessage,
149	                        rejectedValue);
150	                    return new ValidationMessageDto(message)
151	                        .putAdditionalProperty("field", fieldError.getField())
152	                        .putAdditionalProperty("rejectedValue", rejectedValue)
153	                        .putAdditionalProperty("defaultMessage", defaultMessage);
154	                })
155	                .toList();
156	            logger.debug("Validation error at {} {}: {}",
157	                request.getMethod(),
158	                request.getRequestURI(),
159	                bindingResult.getFieldErrors());
160	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
161	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
162	                .map(fieldError -> fieldError.getField())
163	                .distinct()
164	                .toList());
165	            return ResponseEntity.status(status).body(detail);
166	        }
167	        return ResponseEntity.status(status).body(detail);
168	    }
169	
170	    /**
171	     * Handles {@link MissingOwnerFieldsException} raised when an owner payload is missing or blank in one
172	     * or more required fields. Returns a 400 Bad Request whose {@code errors} array lists the name of each
173	     * offending field.
174	     *
175	     * @param e The {@link MissingOwnerFieldsException} to be handled
176	     * @return A {@link ResponseEntity} containing the offending field names and a 400 Bad Request status.
177	     */
178	    @ExceptionHandler(MissingOwnerFieldsException.class)
179	    @ResponseBody
180	    public ResponseEntity<Map<String, Object>> handleMissingOwnerFieldsException(MissingOwnerFieldsException e) {
181	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", e.getFields()));
182	    }
183	
184	    /**
185	     * Handles {@link InvalidTelephoneException} raised when an owner's telephone does not contain
186	     * exactly ten digits once every non-digit character has been stripped. Returns a 400 Bad Request
187	     * whose {@code errors} array names the offending {@code telephone} field.
188	     *
189	     * @param e The {@link InvalidTelephoneException} to be handled
190	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
191	     */
192	    @ExceptionHandler(InvalidTelephoneException.class)
193	    @ResponseBody
194	    public ResponseEntity<Map<String, Object>> handleInvalidTelephoneException(InvalidTelephoneException e) {
195	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", List.of("telephone")));
196	    }
197	
198	    /**
199	     * Handles {@link InvalidEmailException} raised when an owner supplies an {@code email} that is
200	     * not a syntactically valid address. Returns a 400 Bad Request whose {@code errors} array names
201	     * the offending {@code email} field.
202	     *
203	     * @param e The {@link InvalidEmailException} to be handled
204	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
205	     */
206	    @ExceptionHandler(InvalidEmailException.class)
207	    @ResponseBody
208	    public ResponseEntity<Map<String, Object>> handleInvalidEmailException(InvalidEmailException e) {
209	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", List.of("email")));
210	    }
211	
212	    /**
213	     * Handles {@link InvalidPostcodeException} raised when an owner supplies a {@code postcode}
214	     * that is not a 4-digit value or that falls outside the postcode range fixed for the owner's
215	     * city's region. Returns a 400 Bad Request whose {@code errors} array names the offending
216	     * {@code postcode} field.
217	     *
218	     * @param e The {@link InvalidPostcodeException} to be handled
219	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
220	     */
221	    @ExceptionHandler(InvalidPostcodeException.class)
222	    @ResponseBody
223	    public ResponseEntity<Map<String, Object>> handleInvalidPostcodeException(InvalidPostcodeException e) {
224	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", List.of("postcode")));
225	    }
226	
227	    /**
228	     * Handles {@link DuplicateTelephoneException} raised when a new owner's normalized telephone is
229	     * already used by another owner. Returns a 409 Conflict whose {@code errors} array names the
230	     * offending {@code telephone} field.
231	     *
232	     * @param e The {@link DuplicateTelephoneException} to be handled
233	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
234	     */
235	    @ExceptionHandler(DuplicateTelephoneException.class)
236	    @ResponseBody
237	    public ResponseEntity<Map<String, Object>> handleDuplicateTelephoneException(DuplicateTelephoneException e) {
238	        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("errors", List.of("telephone")));
239	    }
240	
241	    /**
242	     * Handles {@link DuplicateEmailException} raised when a new owner's lower-cased email is
243	     * already used by another owner. Returns a 409 Conflict whose {@code errors} array names the
244	     * offending {@code email} field.
245	     *
246	     * @param e The {@link DuplicateEmailException} to be handled
247	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
248	     */
249	    @ExceptionHandler(DuplicateEmailException.class)
250	    @ResponseBody
251	    public ResponseEntity<Map<String, Object>> handleDuplicateEmailException(DuplicateEmailException e) {
252	        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("errors", List.of("email")));
253	    }
254	
255	    /**
256	     * Handles {@link DuplicateHouseholdException} raised when a new owner shares the same last
257	     * name and postcode as an existing owner and the request did not opt in via {@code sharesHousehold}.
258	     * Returns a 409 Conflict whose {@code errors} array names the offending {@code lastName} and
259	     * {@code postcode} fields.
260	     *
261	     * @param e The {@link DuplicateHouseholdException} to be handled
262	     * @return A {@link ResponseEntity} containing the offending field names and a 409 Conflict status.
263	     */
264	    @ExceptionHandler(DuplicateHouseholdException.class)
265	    @ResponseBody
266	    public ResponseEntity<Map<String, Object>> handleDuplicateHouseholdException(DuplicateHouseholdException e) {
267	        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("errors", List.of("lastName", "postcode")));
268	    }
269	
270	    /**
271	     * Handles {@link DuplicateIdentityException} raised when a new owner's whole derived identity
272	     * key ({@code '<telephone>|<email>|<householdId>'}) equals an existing owner's. Returns a 409
273	     * Conflict whose {@code errors} array names the offending {@code identityKey}.
274	     *
275	     * @param e The {@link DuplicateIdentityException} to be handled
276	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
277	     */
278	    @ExceptionHandler(DuplicateIdentityException.class)
279	    @ResponseBody
280	    public ResponseEntity<Map<String, Object>> handleDuplicateIdentityException(DuplicateIdentityException e) {
281	        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("errors", List.of("identityKey")));
282	    }
283	
284	    /**
285	     * Handles {@link CityAtCapacityException} raised when a new owner's city already contains 50 or
286	     * more owners. Returns a 409 Conflict whose {@code errors} array names the offending
287	     * {@code city} field.
288	     *
289	     * @param e The {@link CityAtCapacityException} to be handled
290	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
291	     */
292	    @ExceptionHandler(CityAtCapacityException.class)
293	    @ResponseBody
294	    public ResponseEntity<Map<String, Object>> handleCityAtCapacityException(CityAtCapacityException e) {
295	        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("errors", List.of("city")));
296	    }
297	
298	    /**
299	     * Handles {@link DailyRegistrationLimitException} raised when 100 or more owners have already
300	     * been registered today (by {@code registrationDate}). Returns a 429 Too Many Requests whose
301	     * {@code errors} array names the offending {@code registrationDate} field.
302	     *
303	     * @param e The {@link DailyRegistrationLimitException} to be handled
304	     * @return A {@link ResponseEntity} containing the offending field name and a 429 Too Many Requests status.
305	     */
306	    @ExceptionHandler(DailyRegistrationLimitException.class)
307	    @ResponseBody
308	    public ResponseEntity<Map<String, Object>> handleDailyRegistrationLimitException(DailyRegistrationLimitException e) {
309	        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body(Map.of("errors", List.of("registrationDate")));
310	    }
311	
312	    /**
313	     * Handles {@link FutureRegistrationDateException} raised when an owner supplies a
314	     * {@code registrationDate} that is later than the server's current date. Returns a 400 Bad
315	     * Request whose {@code errors} array names the offending {@code registrationDate} field.
316	     *
317	     * @param e The {@link FutureRegistrationDateException} to be handled
318	     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
319	     */
320	    @ExceptionHandler(FutureRegistrationDateException.class)
321	    @ResponseBody
322	    public ResponseEntity<Map<String, Object>> handleFutureRegistrationDateException(FutureRegistrationDateException e) {
323	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", List.of("registrationDate")));
324	    }
325	
326	}
