package org.springframework.samples.petclinic.rest.advice;

import java.net.URI;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Objects;

import jakarta.servlet.http.HttpServletRequest;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.ResponseBody;

/**
 * Global Exception handler for REST controllers.
 * <p>
 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
 *
 * @author Vitaliy Fedoriv
 * @author Alexander Dudkin
 */
@ControllerAdvice
public class ExceptionControllerAdvice {

    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";

    /**
     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
     * class.
     *
     * @param e     Object referring to the thrown exception.
     * @param status HTTP response status.
     * @param url URL request.
     */
    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
        problemDetail.setType(URI.create(url.toString()));
        problemDetail.setTitle(e.getClass().getSimpleName());
        problemDetail.setDetail(detail);
        problemDetail.setProperty("timestamp", Instant.now());
        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
        return problemDetail;
    }

    /**
     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
     * translates it as it normally would - 403 for an authenticated user lacking the required role,
     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
     * would catch it and report an authorization failure as a 500.
     *
     * @param e The {@link AccessDeniedException} to propagate
     * @throws AccessDeniedException always
     */
    @ExceptionHandler(AccessDeniedException.class)
    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
        throw e;
    }

    /**
     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
     *
     * @param e The {@link Exception} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
     */
    @ExceptionHandler(Exception.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
     * method returns a 404 Not Found status if an entity does not exist.
     *
     * @param e The {@link DataIntegrityViolationException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
     */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
        logger.warn("Data integrity violation at {} {}: {}",
            request.getMethod(),
            request.getRequestURI(),
            e.getMessage());
        logger.debug("Data integrity violation stacktrace", e);
        HttpStatus status = HttpStatus.NOT_FOUND;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles exception thrown by Bean Validation on controller methods parameters
     *
     * @param e The {@link MethodArgumentNotValidException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.BAD_REQUEST;
        BindingErrorsResponse errors = new BindingErrorsResponse();
        BindingResult bindingResult = e.getBindingResult();
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
        if (bindingResult.hasErrors()) {
            errors.addAllErrors(bindingResult);
            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
                .map(fieldError -> {
                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
                    String message = "Field '%s' %s (rejected value: %s)".formatted(
                        fieldError.getField(),
                        defaultMessage,
                        rejectedValue);
                    return new ValidationMessageDto(message)
                        .putAdditionalProperty("field", fieldError.getField())
                        .putAdditionalProperty("rejectedValue", rejectedValue)
                        .putAdditionalProperty("defaultMessage", defaultMessage);
                })
                .toList();
            logger.debug("Validation error at {} {}: {}",
                request.getMethod(),
                request.getRequestURI(),
                bindingResult.getFieldErrors());
            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
                .map(fieldError -> fieldError.getField())
                .distinct()
                .toList());
            return ResponseEntity.status(status).body(detail);
        }
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link MissingOwnerFieldsException} raised when an owner payload is missing or blank in one
     * or more required fields. Returns a 400 Bad Request whose {@code errors} array lists the name of each
     * offending field.
     *
     * @param e The {@link MissingOwnerFieldsException} to be handled
     * @return A {@link ResponseEntity} containing the offending field names and a 400 Bad Request status.
     */
    @ExceptionHandler(MissingOwnerFieldsException.class)
    @ResponseBody
    public ResponseEntity<Map<String, Object>> handleMissingOwnerFieldsException(MissingOwnerFieldsException e) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", e.getFields()));
    }

    /**
     * Handles {@link InvalidTelephoneException} raised when an owner's telephone does not contain
     * exactly ten digits once every non-digit character has been stripped. Returns a 400 Bad Request
     * whose {@code errors} array names the offending {@code telephone} field.
     *
     * @param e The {@link InvalidTelephoneException} to be handled
     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
     */
    @ExceptionHandler(InvalidTelephoneException.class)
    @ResponseBody
    public ResponseEntity<Map<String, Object>> handleInvalidTelephoneException(InvalidTelephoneException e) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", List.of("telephone")));
    }

    /**
     * Handles {@link InvalidEmailException} raised when an owner supplies an {@code email} that is
     * not a syntactically valid address. Returns a 400 Bad Request whose {@code errors} array names
     * the offending {@code email} field.
     *
     * @param e The {@link InvalidEmailException} to be handled
     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
     */
    @ExceptionHandler(InvalidEmailException.class)
    @ResponseBody
    public ResponseEntity<Map<String, Object>> handleInvalidEmailException(InvalidEmailException e) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", List.of("email")));
    }

    /**
     * Handles {@link InvalidPostcodeException} raised when an owner supplies a {@code postcode}
     * that is not a 4-digit value or that falls outside the postcode range fixed for the owner's
     * city's region. Returns a 400 Bad Request whose {@code errors} array names the offending
     * {@code postcode} field.
     *
     * @param e The {@link InvalidPostcodeException} to be handled
     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
     */
    @ExceptionHandler(InvalidPostcodeException.class)
    @ResponseBody
    public ResponseEntity<Map<String, Object>> handleInvalidPostcodeException(InvalidPostcodeException e) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", List.of("postcode")));
    }

    /**
     * Handles {@link DuplicateTelephoneException} raised when a new owner's normalized telephone is
     * already used by another owner. Returns a 409 Conflict whose {@code errors} array names the
     * offending {@code telephone} field.
     *
     * @param e The {@link DuplicateTelephoneException} to be handled
     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
     */
    @ExceptionHandler(DuplicateTelephoneException.class)
    @ResponseBody
    public ResponseEntity<Map<String, Object>> handleDuplicateTelephoneException(DuplicateTelephoneException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("errors", List.of("telephone")));
    }

    /**
     * Handles {@link DuplicateEmailException} raised when a new owner's lower-cased email is
     * already used by another owner. Returns a 409 Conflict whose {@code errors} array names the
     * offending {@code email} field.
     *
     * @param e The {@link DuplicateEmailException} to be handled
     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
     */
    @ExceptionHandler(DuplicateEmailException.class)
    @ResponseBody
    public ResponseEntity<Map<String, Object>> handleDuplicateEmailException(DuplicateEmailException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("errors", List.of("email")));
    }

    /**
     * Handles {@link DuplicateHouseholdException} raised when a new owner shares the same last
     * name and postcode as an existing owner and the request did not opt in via {@code sharesHousehold}.
     * Returns a 409 Conflict whose {@code errors} array names the offending {@code lastName} and
     * {@code postcode} fields.
     *
     * @param e The {@link DuplicateHouseholdException} to be handled
     * @return A {@link ResponseEntity} containing the offending field names and a 409 Conflict status.
     */
    @ExceptionHandler(DuplicateHouseholdException.class)
    @ResponseBody
    public ResponseEntity<Map<String, Object>> handleDuplicateHouseholdException(DuplicateHouseholdException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("errors", List.of("lastName", "postcode")));
    }

    /**
     * Handles {@link DuplicateIdentityException} raised when a new owner's whole derived identity
     * key ({@code '<telephone>|<email>|<householdId>'}) equals an existing owner's. Returns a 409
     * Conflict whose {@code errors} array names the offending {@code identityKey}.
     *
     * @param e The {@link DuplicateIdentityException} to be handled
     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
     */
    @ExceptionHandler(DuplicateIdentityException.class)
    @ResponseBody
    public ResponseEntity<Map<String, Object>> handleDuplicateIdentityException(DuplicateIdentityException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("errors", List.of("identityKey")));
    }

    /**
     * Handles {@link CityAtCapacityException} raised when a new owner's city already contains 50 or
     * more owners. Returns a 409 Conflict whose {@code errors} array names the offending
     * {@code city} field.
     *
     * @param e The {@link CityAtCapacityException} to be handled
     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
     */
    @ExceptionHandler(CityAtCapacityException.class)
    @ResponseBody
    public ResponseEntity<Map<String, Object>> handleCityAtCapacityException(CityAtCapacityException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("errors", List.of("city")));
    }

    /**
     * Handles {@link DailyRegistrationLimitException} raised when 100 or more owners have already
     * been registered today (by {@code registrationDate}). Returns a 429 Too Many Requests whose
     * {@code errors} array names the offending {@code registrationDate} field.
     *
     * @param e The {@link DailyRegistrationLimitException} to be handled
     * @return A {@link ResponseEntity} containing the offending field name and a 429 Too Many Requests status.
     */
    @ExceptionHandler(DailyRegistrationLimitException.class)
    @ResponseBody
    public ResponseEntity<Map<String, Object>> handleDailyRegistrationLimitException(DailyRegistrationLimitException e) {
        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body(Map.of("errors", List.of("registrationDate")));
    }

    /**
     * Handles {@link FutureRegistrationDateException} raised when an owner supplies a
     * {@code registrationDate} that is later than the server's current date. Returns a 400 Bad
     * Request whose {@code errors} array names the offending {@code registrationDate} field.
     *
     * @param e The {@link FutureRegistrationDateException} to be handled
     * @return A {@link ResponseEntity} containing the offending field name and a 400 Bad Request status.
     */
    @ExceptionHandler(FutureRegistrationDateException.class)
    @ResponseBody
    public ResponseEntity<Map<String, Object>> handleFutureRegistrationDateException(FutureRegistrationDateException e) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", List.of("registrationDate")));
    }

}

